// Package openapidoc embeds the generated OpenAPI bundle for the REST surface
// so the binary can serve the spec (and a Redoc docs page) without shipping the
// repo. The yaml is generated by protoc-gen-go-ogen (openapi_out in
// protocols/easyp.api.go.yaml points here).
package openapidoc

import _ "embed"

// Spec is the generated OpenAPI 3 document describing the /api REST surface.
//
//go:embed stroppy-cloud.openapi.yaml
var Spec []byte
